(() => {
  const guides = window.GUIDES, cards = document.querySelector('#cards'), filters = document.querySelector('#filters'), search = document.querySelector('#search'), count = document.querySelector('#result-count'), empty = document.querySelector('#empty'), dialog = document.querySelector('#guide-dialog');
  let category = '全部';
  const cats = ['全部', ...new Set(guides.map(g => g.category))];
  function filterButtons(){ filters.replaceChildren(...cats.map(c => { const b=document.createElement('button'); b.textContent=c; b.className=c===category?'active':''; b.setAttribute('aria-pressed',String(c===category)); b.addEventListener('click',()=>{category=c;filterButtons();render()}); return b; })); }
  function render(){ const q=search.value.trim().toLowerCase(); const found=guides.filter(g => (category==='全部'||g.category===category) && [g.title,g.desc,g.category,...g.tags,...g.steps].join(' ').toLowerCase().includes(q)); count.textContent=`显示 ${found.length} / ${guides.length} 篇`; empty.hidden=found.length>0; cards.replaceChildren(...found.map(g=>{const b=document.createElement('button'); b.className='card'; b.setAttribute('aria-label',`阅读 ${g.title}`); const icon=document.createElement('span'); icon.className='card-icon'; icon.textContent=g.icon; const arrow=document.createElement('span'); arrow.className='arrow'; arrow.textContent='↗'; const categoryLabel=document.createElement('span'); categoryLabel.className='card-cat'; categoryLabel.textContent=g.category; const title=document.createElement('h3'); title.textContent=g.title; const desc=document.createElement('p'); desc.textContent=g.desc; const foot=document.createElement('span'); foot.className='card-foot'; foot.textContent='查看指南 →'; b.append(icon,arrow,categoryLabel,title,desc,foot); b.addEventListener('click',()=>openGuide(g)); return b;})); }
  function openGuide(g){ document.querySelector('#detail-category').textContent=g.category+' / GUIDEBOOK'; const root=document.querySelector('#detail-content'); root.replaceChildren(); const h=document.createElement('h2');h.id='detail-title';h.textContent=g.title;const p=document.createElement('p');p.className='detail-lead';p.textContent=g.desc;const heading=document.createElement('h3');heading.textContent='操作步骤';const ol=document.createElement('ol');g.steps.forEach(s=>{const li=document.createElement('li');li.textContent=s;ol.append(li)});const note=document.createElement('div');note.className='detail-note';note.textContent=g.note;const a=document.createElement('a');a.href=g.source;a.target='_blank';a.rel='noopener noreferrer';a.className='detail-source';a.textContent='查看原始教程 ↗';root.append(h,p,heading,ol,note,a);dialog.showModal(); }
  document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close()); dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()}); search.addEventListener('input',render);document.querySelectorAll('[data-search]').forEach(b=>b.addEventListener('click',()=>{search.value=b.dataset.search;category='全部';filterButtons();render();search.focus()}));document.querySelector('#reset').addEventListener('click',()=>{search.value='';category='全部';filterButtons();render();search.focus()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!dialog.open&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();search.focus()}});document.querySelector('#total').textContent=guides.length;filterButtons();render();
})();
